// AuthoredCommand is a workflow command (set-output, save-state, set-env or add-path) whose name is in the text of a run of bash or sh and that the run prints to its log (taint.AuthoredCommand).
type AuthoredCommand struct {
	Command analysis.AuthoredCommandName // the command
	At      Handle                       // the name in the run
}

func (x AuthoredCommand) equal(y AuthoredCommand) bool {
	return true &&
		x.Command == y.Command
}

// AutomaticApproval is how a step of the repository that runs actions/labeler on an attacker's pull request lets a labeled run of the job in (actions/labeler): the automatic labels, the label, where the token of the step comes from, the step, and the environment of the job.
type AutomaticApproval struct {
	AutomaticLabels []analysis.AutomaticLabel // AutomaticLabelFree alone, or the conditions that leave it undecided; none when no labeler lets the attacker in
	LabelNames      []analysis.LabelName      // the labels of the configuration that let the run in, in the order of their names; none when the attacker writes the configuration or it is not known
	Token           labeler.TokenSource       // where the token of the labeler comes from, which decides the actor of the labeled run
	Environment     facts.EnvironmentName     // the environment of the job, written out, when AutomaticLabels is AutomaticLabelFree: it approves the run when it has required reviewers
	At              Handle                    // the step of the labeler, in its workflow
}

func (x AutomaticApproval) equal(y AutomaticApproval) bool {
	return true &&
		slices.Equal(x.AutomaticLabels, y.AutomaticLabels) &&
		slices.Equal(x.LabelNames, y.LabelNames) &&
		x.Token == y.Token &&
		x.Environment == y.Environment
}

// CacheSaveStep is a step that saves to the cache what a checkout brings (actions/prcode).
type CacheSaveStep struct {
	Name        string                   // the step's name, else steps[<n>]
	Step        Key                      // the step, as its CacheSave names it
	Action      analysis.CacheAction     // actions/cache, which saves at the end of the job, or actions/cache/save
	Line        string                   // the line of its path that has the tree, as written
	Known       bool                     // whether the line is known: false when a ${{ }} that is not the workspace's decides it
	SaveOn      []analysis.EventActivity // of the site's cacheWriteOn, the events the step's if lets through: those on which it saves the tree
	Via         []composite.Hop          // for a step of a composite action that a step of the job runs (actions/composite), the uses from that step to the action the cache step is of, that action's last; none for a step of the job
	Substituted bool                     // whether the action the step is of has a file in the archive the runner downloads unlike its blob (export-subst), whose content may change after the run
	At          Handle                   // its path, else its with; for a step of a composite action, the uses of the step of the job that runs the action
	PathAt      Handle                   // for a step of a composite action, its path, else its with, in the file it is written in (an input, or the value of action.definition); zero for a step of the job
}

func (x CacheSaveStep) equal(y CacheSaveStep) bool {
	return true &&
		x.Name == y.Name &&
		x.Step == y.Step &&
		x.Action == y.Action &&
		x.Line == y.Line &&
		x.Known == y.Known &&
		slices.Equal(x.SaveOn, y.SaveOn) &&
		slices.Equal(x.Via, y.Via) &&
		x.Substituted == y.Substituted
}

// CalledJob is a job of a reusable workflow of another repository that a job of the input calls (actions/composite.Reader.ExpandCall): the labels of its runs-on and its cache-mode.
type CalledJob struct {
	ID                 string              // the ID of the job, as written
	Chain              []composite.Hop     // the uses from the calling job to the workflow the job is of, that workflow's last
	Query              facts.Query         // the workflow.definition whose value is the file the job is written in
	RunnerLabels       []RunnerLabel       // the labels of its runs-on
	InconclusiveLabels []InconclusiveLabel // the labels of its runs-on that are inconclusive
	CacheModeText      string              // its cache-mode as written; empty when it writes none
	CacheModeAt        Handle              // its cache-mode, else the job
	At                 Handle              // the job, in the file it is written in
}

func (x CalledJob) equal(y CalledJob) bool {
	return true &&
		x.ID == y.ID &&
		slices.Equal(x.Chain, y.Chain) &&
		x.Query == y.Query &&
		slices.EqualFunc(x.RunnerLabels, y.RunnerLabels, RunnerLabel.equal) &&
		slices.EqualFunc(x.InconclusiveLabels, y.InconclusiveLabels, InconclusiveLabel.equal) &&
		x.CacheModeText == y.CacheModeText
}

// CallsNotRead is the first call of a function whose body the readings of a run did not read past their limit of calls.
type CallsNotRead struct {
	At Handle // where the call is
}

func (x CallsNotRead) equal(y CallsNotRead) bool {
	return true
}

// CapabilityGrant is a capability a permission of a step of an agent action gives its agent (actions/agent): through the permission alone, or with an edit of the workspace (Partner) whose code the permitted command runs.
type CapabilityGrant struct {
	Capability analysis.AgentCapability // what it lets the agent do
	Input      analysis.AgentInput      // the input the permission is in; unset for one the action allows on its own
	Permission string                   // the permission as written, or as the action writes it
	At         Handle                   // the permission in its input, the input's value, or the uses
	Partner    string                   // the permission to edit whose edits the permitted command runs; empty when there is none
	PartnerAt  Handle                   // where Partner is
}

func (x CapabilityGrant) equal(y CapabilityGrant) bool {
	return true &&
		x.Capability == y.Capability &&
		x.Input == y.Input &&
		x.Permission == y.Permission &&
		x.Partner == y.Partner
}

// CarriedSecret is a secret a request carries (actions/taint): by name, the job's token, or the whole secrets context.
type CarriedSecret struct {
	Name  string // the secret's name as written; empty for the job's token
	Token bool   // the job's token: secrets.GITHUB_TOKEN or github.token
	Whole bool   // the whole secrets context: toJSON(secrets), secrets[x]
	At    Handle // where the request takes it: the ${{ }}, the variable, or the command for gh api's enterprise token; none for an action's
}

func (x CarriedSecret) equal(y CarriedSecret) bool {
	return true &&
		x.Name == y.Name &&
		x.Token == y.Token &&
		x.Whole == y.Whole
}

// CheckoutRef is a reference to a pull request's code in the with of a checkout.
type CheckoutRef struct {
	Text    string                 // as written
	Input   analysis.CheckoutInput // the input it is in
	Mutable bool                   // a branch's name, or a ref GitHub moves
	At      Handle                 // where it is
}

func (x CheckoutRef) equal(y CheckoutRef) bool {
	return true &&
		x.Text == y.Text &&
		x.Input == y.Input &&
		x.Mutable == y.Mutable
}

// CodeRunStep is a step after a checkout that runs the code it brings.
type CodeRunStep struct {
	Name string // the step's name, else steps[<n>]
	Text string // the command or the uses, as written
	Cite string // the https URL of why the row of the table runs code of the tree
	At   Handle // the command in the run, else the uses, else the step
}

func (x CodeRunStep) equal(y CodeRunStep) bool {
	return true &&
		x.Name == y.Name &&
		x.Text == y.Text &&
		x.Cite == y.Cite
}

// CommandArgument is a word of a simple command of a run of bash or sh with a value an attacker may control in it, and how the command reads the word (actions/taint).
type CommandArgument struct {
	Command       string                   // the command and its subcommands, such as git fetch
	Known         bool                     // the table of commands has the command
	Word          int                      // the index of the word among the command's words
	OptionPlace   bool                     // the command may read as an option a word the value starts: the word, at the place of options, and the value at its head; or, for a value outside quotes that can hold blanks, a word it splits into
	Undecided     bool                     // the word before it is an option the table of commands does not declare, which may take it as its value
	Runs          bool                     // the command declares an option that runs a program: one seen to in an attacker's spelling, or one read as code or a program
	Spelled       []string                 // the options seen to run a program in a spelling the attacker can write with this value, as they write them: a long option with = for one word (--to-command=), a short option alone for one word or two (-e, -c); an option whose program runs on the remote side only when the command names a repository on a local path, where the program runs on the runner
	Remote        bool                     // an option seen to run a program on the remote side can be written, and the command names no repository on a local path nor one of HTTPS: the program runs on the remote host of an SSH remote, or where the repository decides at run time
	RemoteSSH     bool                     // with Remote: the command names an SSH remote, where the program runs on the remote host
	RepoName      bool                     // every value that may begin with - is the name of a repository, which holds only ASCII letters, digits, ., - and _: the attacker writes only a short option with its value joined in one word
	Unverified    bool                     // a spelling the attacker can write is, for an option that runs a program, seen neither to run it nor not to
	Ref           ExprRef                  // the reference: the ${{ }}, or what env gives the variable
	Path          string                   // the context path of the reference, such as github.head_ref: of the ${{ }}, or of the reference in the env value, the same before and after a fix moves the ${{ }} into env
	LeadingDash   []analysis.EventActivity // the events on which an attacker can make the value begin with -
	DashUndecided []analysis.EventActivity // the events, not of LeadingDash, on which whether an attacker can make the value begin with - is not known
	Head          bool                     // the value is at the head of the word
	Blanks        bool                     // an attacker can write blanks in the value: one of the events is one on which they write it freely
	Quoted        bool                     // the word is inside quotes
	At            Handle                   // the ${{ }} or the variable in the run
}

func (x CommandArgument) equal(y CommandArgument) bool {
	return true &&
		x.Command == y.Command &&
		x.Known == y.Known &&
		x.Word == y.Word &&
		x.OptionPlace == y.OptionPlace &&
		x.Undecided == y.Undecided &&
		x.Runs == y.Runs &&
		slices.Equal(x.Spelled, y.Spelled) &&
		x.Remote == y.Remote &&
		x.RemoteSSH == y.RemoteSSH &&
		x.RepoName == y.RepoName &&
		x.Unverified == y.Unverified &&
		x.Ref.equal(y.Ref) &&
		x.Path == y.Path &&
		slices.Equal(x.LeadingDash, y.LeadingDash) &&
		slices.Equal(x.DashUndecided, y.DashUndecided) &&
		x.Head == y.Head &&
		x.Blanks == y.Blanks &&
		x.Quoted == y.Quoted
}

// CompositeAction is an action a step runs, or that a step of a composite action it runs runs, to the depth composite.Reader reads (actions/composite): an action.yml of the inputs, or the file action.definition answers for an action of another repository.
